import React, { createContext, useContext, useState, useEffect } from 'react';
import { getData, saveData } from '../services/localStorageService';
import { generateId } from '../utils/helpers';
import { useAuth } from './AuthContext';

const BookingContext = createContext();

export const PENALTY_RATE = 0.05; // 5% cancellation penalty

export const BookingProvider = ({ children }) => {
  const { currentUser } = useAuth();
  const [bookings, setBookings] = useState([]);

  useEffect(() => {
    if (currentUser) {
      const all = getData('bookings');
      setBookings(all.filter(b => b.userId === currentUser.id));
    } else {
      setBookings([]);
    }
  }, [currentUser]);

  const saveBookings = (updated) => {
    const all = getData('bookings');
    const others = all.filter(b => b.userId !== currentUser.id);
    saveData('bookings', [...others, ...updated]);
    setBookings(updated);
  };

  const addBooking = (item, type) => {
    if (!currentUser) return null;
    const existing = bookings.find(b => b.itemId === item.id && b.type === type && b.status === 'confirmed');
    if (existing) return existing;
    const booking = {
      id: generateId(),
      userId: currentUser.id,
      itemId: item.id,
      type, // 'package' | 'hotel' | 'trip'
      title: item.title || item.name,
      image: item.image,
      price: item.price,
      destination: item.destination || item.location,
      duration: item.duration || null,
      status: 'confirmed',
      bookedAt: new Date().toISOString(),
    };
    const updated = [...bookings, booking];
    saveBookings(updated);
    return booking;
  };

  const cancelBooking = (bookingId) => {
    const updated = bookings.map(b =>
      b.id === bookingId ? { ...b, status: 'cancelled', cancelledAt: new Date().toISOString() } : b
    );
    saveBookings(updated);
  };

  const completeBooking = (bookingId) => {
    const updated = bookings.map(b =>
      b.id === bookingId ? { ...b, status: 'completed', completedAt: new Date().toISOString() } : b
    );
    saveBookings(updated);
  };

  const deleteBooking = (bookingId) => {
    const updated = bookings.filter(b => b.id !== bookingId);
    saveBookings(updated);
  };

  const isBooked = (itemId, type) =>
    bookings.some(b => b.itemId === itemId && b.type === type && b.status === 'confirmed');

  const getBookingByItem = (itemId, type) =>
    bookings.find(b => b.itemId === itemId && b.type === type && b.status === 'confirmed');

  return (
    <BookingContext.Provider value={{ bookings, addBooking, cancelBooking, completeBooking, deleteBooking, isBooked, getBookingByItem, PENALTY_RATE }}>
      {children}
    </BookingContext.Provider>
  );
};

export const useBookings = () => useContext(BookingContext);
export default BookingContext;
